"#d3e1e9\"/><path d=\"m-12-7 12 6 12-6M0-1v9\" fill=\"none\" stroke=\"#a5b8ca\"/><rect x=\"-6\" y=\"-7\" width=\"12\" height=\"5\" rx=\"2\" fill=\"#36597b\"/><path d=\"M-19-3h6m26 0h6\" stroke=\"#bcd2df\" stroke-width=\"3\"/><ellipse cx=\"-20\" cy=\"-3\" rx=\"6\" ry=\"2\" fill=\"#486b8e\"/><ellipse cx=\"20\" cy=\"-3\" rx=\"6\" ry=\"2\" fill=\"#486b8e\"/></g></g></svg>";const campus=()=>WORLD_PREVIEW;
const dialog = document.getElementById('game-dialog');
const dialogBody = document.getElementById('dialog-body');
const screen = document.querySelector('[data-screen]').dataset.screen;
let opener, toastTimer;
let growthStage = 0;
const levels = [
  {name:'Just One Small Feature',description:'Build the Product. Defend it from Problems.',status:'RUN IN PROGRESS'},
  {name:'Scope Creep',description:'One more request. And another. A future level about an ever-growing scope.',status:'FUTURE LEVEL CONCEPT'},
  {name:'Release Friday',description:'The release is close. The weekend is closer. A future level theme.',status:'FUTURE LEVEL CONCEPT'}
];
const characters = [
  {name:'Developer',color:'#2769ab',type:'dev',role:'The throughput specialist.',traits:['Completes Work faster','Resolves Problems faster'],description:'More direct throughput for both Work and Problems. Specialize a placed Base Copilot during a level.',unlock:'Available from the start.'},
  {name:'Tester',color:'#cfaa5e',type:'tester',role:'Better together.',traits:['Quality Aura slows Problems','Nearby completed Work earns bonus Compute'],description:'Works and defends while a Quality Aura improves nearby outcomes. Aura effects do not stack.',unlock:'Available from the start.'},
  {name:'Analyst',color:'#96a0b8',type:'dev',role:'Clarity starts upstream.',traits:['Requirement clarity','Upstream prevention'],description:'A future specialist focused on reducing ambiguity before it becomes missed Work and Technical Debt.',unlock:'Complete Level 01 to unlock permanently.'},
  {name:'Security',color:'#7e95ac',type:'tester',role:'Eyes on the unexpected.',traits:['Hidden threat detection','Security specialization'],description:'A future specialist for hidden or high-severity security threats.',unlock:'Unlock through a later milestone. Details to be designed.'}
];
function setDialog(label,body){
  if(!dialog.open)opener=document.activeElement;
  const headings={'SELECT LEVEL':['DEPLOYMENT','Choose your next challenge'],'YOUR COPILOTS':['COPILOT LAB','A small team. Big possibilities.'],'YOUR PRODUCT':['PRODUCT CORE','Something worth protecting.'],'SETTINGS':['OPERATIONS','Make yourself at home.'],'CONTINUE RUN':['CONTINUE RUN','Back to building something great.'],'LEVEL 01':['NEW RUN','Every great Product starts somewhere.'],'PLAN YOUR NEXT MOVE':['PLANNING','Take your time. Make it count.']};
  const [title,subtitle]=headings[label]||[label,'GLACIER / FIELD GUIDE'];
  document.getElementById('dialog-title').textContent=title;
  document.getElementById('dialog-subtitle').textContent=subtitle;
  dialog.dataset.view=label.toLowerCase().replaceAll(' ','-');
  dialogBody.innerHTML=body;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;dialogBody.scrollTop=0;(dialogBody.querySelector('input,button')||document.getElementById('dialog-close')).focus({preventScroll:true});
}
function closeDialog(){dialog.close();if(opener?.isConnected)opener.focus()}
function notify(message){clearTimeout(toastTimer);const t=document.getElementById('toast');t.textContent=message;toastTimer=setTimeout(()=>t.textContent='',3500)}
function openLevels(){setDialog('SELECT LEVEL','<div class="campaign-route">'+levels.map((l,i)=>'<button class="level-choice '+(i===0?'level-ready':'level-future')+'" data-mission="'+i+'"><span class="level-emblem">'+icon(i===0?'product':i===1?'missions':'lock')+'</span><span class="level-summary"><small>LEVEL 0'+(i+1)+' / '+(i===0?'IN PROGRESS':'ON THE HORIZON')+'</small><h3>'+l.name+'</h3><p>'+(i===0?'Build the Product. Defend it from Problems.':i===1?'The backlog keeps growing.':'One last push before the weekend.')+'</p></span><span class="level-end">'+icon(i===0?'arrow':'lock')+'</span></button>').join('')+'</div><div class="campaign-reward">'+bot('#96a0b8','dev')+'<span><small>YOUR NEXT MILESTONE</small><strong>Finish Level 01. Meet the Analyst.</strong></span>'+icon('lock')+'</div><p class="overlay-note center">Future levels are theme previews.</p>')}
function openBriefing(resume=true,world=0){
  if(world>0){setDialog(levels[world].name,'<div class="brief-grid"><div class="brief-art locked-art">'+campus('future-'+world)+'</div><div class="brief-copy"><span class="status-tag">'+icon('lock')+' FUTURE LEVEL</span><h3>More stories ahead.</h3><p style="font-size:13px;line-height:1.6">'+levels[world].description+'</p></div></div><div class="dialog-actions"><button class="game-button" data-action="missions">ALL LEVELS</button><button class="game-button primary" data-action="continue">'+icon('play')+' LEVEL 01</button></div><p class="overlay-note">Theme preview. Its waves, boss, and unlock conditions are still to be designed.</p>');return}
  setDialog(resume?'CONTINUE RUN':'LEVEL 01','<div class="brief-grid"><div class="brief-art">'+campus('briefing')+'</div><div class="brief-copy"><span class="status-tag">'+icon('play')+' '+(resume?'SAVED BETWEEN WAVES':'READY TO BUILD')+'</span><h3>Just One<br>Small Feature</h3><div class="mini-status">'+icon('missions')+' '+(resume?'Round 4 · Planning':'Round 1 · Planning')+'</div><div class="mini-status">'+icon('team')+' Developer + Tester available</div><div class="mini-status">'+icon('lock')+' Finish the level → Unlock Analyst</div></div></div><div class="dialog-actions"><button class="game-button" data-action="close">BACK</button><button class="game-button primary" data-planning="'+(resume?'resume':'new')+'">'+icon('play')+' ENTER PLANNING</button></div><p class="overlay-note center">UI prototype · Sample run. Opens a planning preview.</p>');
}
function openPlanning(resume){setDialog('PLAN YOUR NEXT MOVE','<div class="planning-stage"><div class="planning-hud"><span class="status-tag">ROUND '+(resume?'4':'1')+' / ~8</span><span class="status-tag">PLANNING</span></div>'+campus('plan')+'<span class="planning-unit" aria-hidden="true"></span></div><div class="mode-panel"><h3>DEVELOPER</h3><button class="game-button" data-mode="Build" aria-pressed="false">BUILD</button><button class="game-button" data-mode="Defend" aria-pressed="false">DEFEND</button><button class="game-button selected" data-mode="Auto" aria-pressed="true">AUTO</button></div><p class="mode-help" id="mode-help">Auto: handles visible Problems before visible Work.</p><div class="dialog-actions"><button class="game-button primary" data-action="close">'+icon('home')+' BACK TO HUB</button></div><p class="overlay-note center">Planning UI preview · Gameplay is not connected.</p>')}
function openTeam(){setDialog('YOUR COPILOTS','<div class="collection-intro"><span>PERSONA COLLECTION</span><strong>02 <small>/ 04 AVAILABLE</small></strong></div><div class="collection">'+characters.map((c,i)=>'<button class="persona-card '+(i>1?'persona-locked':'persona-ready')+'" data-persona="'+i+'" style="--persona-color:'+c.color+'"><span class="persona-slot">0'+(i+1)+'</span><div class="persona-plinth '+(i>1?'locked-art':'')+'">'+bot(c.color,c.type)+'</div><h3>'+c.name+'</h3><span class="persona-status">'+icon(i<2?'check':'lock')+(i<2?'AVAILABLE':i===2?'FINISH LEVEL 01':'LATER MILESTONE')+'</span></button>').join('')+'</div><p class="overlay-note center">Place a Base Copilot. Specialize during the level.</p>')}
function openPersona(index){const c=characters[index];setDialog(c.name,'<div class="persona-detail"><div class="'+(index>1?'locked-art':'')+'">'+bot(c.color,c.type)+'</div><div><span class="status-tag">'+icon(index<2?'check':'lock')+' '+(index<2?'AVAILABLE':'LOCKED')+'</span><h3>'+c.role+'</h3><p>'+c.description+'</p><div class="trait-list">'+c.traits.map(t=>'<span>'+icon('check')+t+'</span>').join('')+'</div><p style="margin-top:20px;font-weight:800;font-size:11px">'+c.unlock+'</p></div></div><div class="dialog-actions"><button class="game-button" data-action="team">ALL COPILOTS</button><button class="game-button primary" data-action="close">DONE</button></div>')}
function openProduct(stage=0){growthStage=stage;const stages=['A SMALL BEGINNING','ROOM TO GROW','SOMETHING WORTH PROTECTING'];setDialog('YOUR PRODUCT','<div class="growth-view" id="growth-view">'+campus('growth')+'</div><h3 class="growth-title">'+stages[stage]+'</h3><div class="growth-controls" aria-label="Growth preview">'+stages.map((s,i)=>'<button class="game-button '+(i===stage?'selected':'')+'" data-growth="'+i+'" aria-pressed="'+(i===stage)+'" aria-label="'+s+'">0'+(i+1)+'</button>').join('')+'</div><p class="overlay-note center">Visual growth preview · Completed Work grows your Product after successful levels.<br>Growth grants no combat-stat bonus.</p>');document.querySelector('#growth-view .product-building').style.transform='scale('+(0.78+stage*.21)+')'}
function openSettings(){
 const options=[['motion-setting','01','Reduce motion','Keep the campus and Copilots still.',document.body.classList.contains('reduced-motion')],['contrast-setting','02','Higher contrast','Give text and controls a stronger outline.',document.body.classList.contains('high-contrast')],['sound-setting','03','Interface sounds','A little feedback for every selection.',interfaceSound]];
 setDialog('SETTINGS','<div class="options-menu"><div class="options-section">COMFORT & FEEDBACK</div>'+options.map(([id,num,name,description,on])=>'<label class="setting-row"><span class="option-number">'+num+'</span><span class="option-copy"><strong>'+name+'</strong><p>'+description+'</p></span><input id="'+id+'" type="checkbox" '+(on?'checked':'')+'><span class="option-value" aria-hidden="true"><span>‹</span><b class="value-off">OFF</b><b class="value-on">ON</b><span>›</span></span></label>').join('')+'<div class="dialog-actions"><button class="game-button" data-action="help">HOW TO PLAY</button><button class="game-button primary" data-action="close">'+icon('arrow')+' BACK TO GARDEN</button></div></div>');
}

function openHelp(){setDialog('BUILD. DEFEND. REPEAT.','<div class="trait-list" style="font-size:14px;gap:23px"><span>'+icon('product')+' Complete Work to earn Compute and grow the Product.</span><span>'+icon('team')+' Specialize Copilots as Developers or Testers.</span><span>'+icon('missions')+' Plan between waves. Start when you are ready.</span><span>'+icon('lock')+' Defeat the Production Incident to unlock the Analyst.</span></div><p class="overlay-note">Unfinished Work adds Technical Debt. Clean it up before the final encounter.</p><div class="dialog-actions"><button class="game-button primary" data-action="continue">'+icon('play')+' CONTINUE</button></div>')}
async function toggleFullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{notify('Fullscreen is unavailable in this browser panel.')}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.persona!==undefined){openPersona(+b.dataset.persona);return}if(b.dataset.mission!==undefined){openBriefing(false,+b.dataset.mission);return}if(b.dataset.planning){openPlanning(b.dataset.planning==='resume');return}if(b.dataset.growth!==undefined){const stage=+b.dataset.growth;openProduct(stage);document.querySelector('[data-growth="'+stage+'"]').focus();return}if(b.dataset.mode){document.querySelectorAll('[data-mode]').forEach(c=>{c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',String(c===b))});document.getElementById('mode-help').textContent={Build:'Build: completes productive Work and cleanup. Ignores Problems.',Defend:'Defend: resolves Problems. Ignores Work and cleanup.',Auto:'Auto: handles visible Problems before visible Work.'}[b.dataset.mode];return}({continue:()=>openBriefing(),missions:openLevels,team:openTeam,product:()=>openProduct(growthStage),settings:openSettings,help:openHelp,close:closeDialog,fullscreen:toggleFullscreen})[b.dataset.action]?.()});
document.addEventListener('keydown',e=>{if(!dialog.open&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&e.key==='Enter'&&document.activeElement===document.body){e.preventDefault();openBriefing(true)}});
const preferencesKey='tower-hub-v05-glacier-'+screen+'-preferences';
try{const p=JSON.parse(localStorage.getItem(preferencesKey)||'{}');document.body.classList.toggle('reduced-motion',!!p.motion);document.body.classList.toggle('high-contrast',!!p.contrast)}catch{}
document.addEventListener('change',e=>{if(!['motion-setting','contrast-setting'].includes(e.target.id))return;document.body.classList.toggle(e.target.id==='motion-setting'?'reduced-motion':'high-contrast',e.target.checked);try{localStorage.setItem(preferencesKey,JSON.stringify({motion:document.body.classList.contains('reduced-motion'),contrast:document.body.classList.contains('high-contrast')}))}catch{notify('Preference applied for this visit. Storage is unavailable.')}});
dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});

const zoneData={product:true,team:true,missions:true,settings:true};
let chosenZone='product';
function highlightZone(id,temporary=false){
  if(!zoneData[id])return;
  document.querySelectorAll('.world-zone').forEach(el=>{el.classList.toggle('is-current',el.dataset.zone===id);el.classList.toggle('is-hover',temporary&&el.dataset.zone===id)});
  document.querySelectorAll('.site-pin').forEach(el=>el.classList.toggle('is-current',el.dataset.zone===id));
}
function enterZone(target){const id=target.dataset.zone;if(!zoneData[id])return;chosenZone=id;highlightZone(id);target.focus();({product:()=>openProduct(growthStage),team:openTeam,missions:openLevels,settings:openSettings})[id]()}
document.addEventListener('click',e=>{const target=e.target.closest('[data-zone]');if(target)enterZone(target)});
document.addEventListener('pointerover',e=>{const target=e.target.closest('[data-zone]');if(target)highlightZone(target.dataset.zone,true)});
document.addEventListener('pointerout',e=>{const target=e.target.closest('[data-zone]');if(target&&!target.contains(e.relatedTarget))highlightZone(chosenZone)});
document.addEventListener('focusin',e=>{const target=e.target.closest('[data-zone]');if(target)highlightZone(target.dataset.zone,true)});
document.addEventListener('keydown',e=>{
  if(dialog.open)return;
  const target=e.target.closest?.('.world-zone[data-zone]');
  if(target&&(e.key==='Enter'||e.key===' ')){e.preventDefault();enterZone(target);return}
  if((e.key==='ArrowLeft'||e.key==='ArrowRight')&&!e.altKey&&!e.ctrlKey&&!e.metaKey){const ids=Object.keys(zoneData),current=document.activeElement.dataset.zone||chosenZone;const next=ids[(ids.indexOf(current)+(e.key==='ArrowRight'?1:ids.length-1))%ids.length];e.preventDefault();document.querySelector('.site-pin[data-zone="'+next+'"]').focus()}
});
dialog.addEventListener('close',()=>highlightZone(chosenZone));

let interfaceSound=false;
try{interfaceSound=localStorage.getItem('tower-garden-v05-glacier-sound')==='on'}catch{}
let soundContext;
function updateSoundButton(){const b=document.querySelector('.sound-toggle');b.setAttribute('aria-pressed',String(interfaceSound));b.setAttribute('aria-label',interfaceSound?'Mute interface sounds':'Enable interface sounds')}
function soundTap(confirm=false){if(!interfaceSound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;soundContext??=new AC();if(soundContext.state==='suspended')void soundContext.resume();const start=soundContext.currentTime,osc=soundContext.createOscillator(),gain=soundContext.createGain();osc.type='sine';osc.frequency.setValueAtTime(confirm?680:540,start);osc.frequency.exponentialRampToValueAtTime(confirm?1020:690,start+.065);gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.022,start+.009);gain.gain.exponentialRampToValueAtTime(.0001,start+.10);osc.connect(gain);gain.connect(soundContext.destination);osc.start(start);osc.stop(start+.115)}catch{}}
updateSoundButton();
document.addEventListener('change',e=>{if(e.target.id!=='sound-setting')return;interfaceSound=e.target.checked;try{localStorage.setItem('tower-garden-v05-glacier-sound',interfaceSound?'on':'off')}catch{}updateSoundButton();soundTap(true)});
dialog.addEventListener('keydown',e=>{
 if(e.altKey||e.ctrlKey||e.metaKey)return;
 const controls=[...dialogBody.querySelectorAll('button,input')].filter(el=>!el.disabled&&el.getClientRects().length);
 const current=controls.indexOf(document.activeElement);
 if(e.key==='ArrowDown'||e.key==='ArrowUp'){
  if(!controls.length)return;e.preventDefault();const step=e.key==='ArrowDown'?1:-1;const next=current<0?(step>0?0:controls.length-1):(current+step+controls.length)%controls.length;controls[next].focus();controls[next].closest('.setting-row')?.scrollIntoView({block:'nearest'});
 }
 if(document.activeElement.matches('input[type=checkbox]')&&['ArrowLeft','ArrowRight','Enter'].includes(e.key)){
  e.preventDefault();const input=document.activeElement;input.checked=e.key==='ArrowLeft'?false:e.key==='ArrowRight'?true:!input.checked;input.dispatchEvent(new Event('change',{bubbles:true}));
 }
});
document.addEventListener('click',e=>{const target=e.target.closest('button,[role=button]');if(!target)return;if(target.dataset.polish==='sound'){interfaceSound=!interfaceSound;try{localStorage.setItem('tower-garden-v05-glacier-sound',interfaceSound?'on':'off')}catch{}updateSoundButton();soundTap(true);return}if(target.dataset.polish==='new-run')openBriefing(false);soundTap(target.dataset.action==='continue'||!!target.dataset.planning)});
const gardenStage=document.querySelector('.world-stage');
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
const coarsePointer=matchMedia('(pointer: coarse)');
function resetLook(){gardenStage.style.setProperty('--look-x','0px');gardenStage.style.setProperty('--look-y','0px')}
document.querySelector('main').addEventListener('pointermove',e=>{if(dialog.open||coarsePointer.matches||innerWidth<900||motionPreference.matches||document.body.classList.contains('reduced-motion'))return;gardenStage.style.setProperty('--look-x',((e.clientX/innerWidth-.5)*5).toFixed(2)+'px');gardenStage.style.setProperty('--look-y',((e.clientY/innerHeight-.5)*3).toFixed(2)+'px')});
document.querySelector('main').addEventListener('pointerleave',resetLook);
window.addEventListener('resize',resetLook);
motionPreference.addEventListener('change',resetLook);
document.addEventListener('change',e=>{if(e.target.id==='motion-setting')resetLook()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)resetLook()});

// Direct campus keyboard shortcuts.
{
 const destinations=['product','team','missions','settings'];
 document.querySelectorAll('.site-pin').forEach(pin=>{const number=destinations.indexOf(pin.dataset.zone)+1;pin.setAttribute('aria-keyshortcuts',String(number))});
 document.querySelector('.keyboard-hint').innerHTML='<kbd>1</kbd><kbd>2</kbd><kbd>3</kbd><kbd>4</kbd> OPEN DESTINATION <kbd>ESC</kbd> BACK';
 document.addEventListener('keydown',e=>{if(dialog.open||e.altKey||e.metaKey||e.ctrlKey||e.repeat||e.target.closest('input,textarea,select,[contenteditable=true]'))return;const id=destinations[+e.key-1];if(id&&/^[1-4]$/.test(e.key)){e.preventDefault();enterZone(document.querySelector('.site-pin[data-zone="'+id+'"]'))}});
}
